    /**
     * @ignore
     * @method
     * @name massive#parseRfc3339
     * @description parses an rfc3339 datetime carrying an explicit utc offset, which the base parse8601 does not accept
     * @param {string} datetime an rfc3339 datetime, e.g. 2020-11-10T17:37:37-05:00
     * @returns {int} the unix timestamp in milliseconds
     */
    public virtual object parseRfc3339(object datetime)
    {
        if (isTrue(isEqual(datetime, null)))
        {
            return null;
        }
        // the trailing 6 characters are the utc offset, e.g. -05:00, on anything
        // shorter or on a 'Z' suffixed datetime the sign check below falls through
        object offsetPart = slice(datetime, -6, null);
        object sign = slice(offsetPart, 0, 1);
        if (isTrue(isTrue((!isEqual(sign, "+"))) && isTrue((!isEqual(sign, "-")))))
        {
            return this.parse8601(datetime);
        }
        object timestamp = this.parse8601(add(slice(datetime, 0, -6), "Z"));
        if (isTrue(isEqual(timestamp, null)))
        {
            return null;
        }
        object hours = this.parseToInt(slice(offsetPart, 1, 3));
        object minutes = this.parseToInt(slice(offsetPart, 4, 6));
        object offset = multiply(multiply(this.sum(multiply(hours, 60), minutes), 60), 1000);
        if (isTrue(isEqual(sign, "-")))
        {
            return this.sum(timestamp, offset);
        }
        return subtract(timestamp, offset);
    }

