    public override object parseTicker(object ticker, object market = null)
    {
        object day = this.safeDict(ticker, "day");
        if (isTrue(isEqual(day, null)))
        {
            // aggregate bar shape, returned by the previous day bar and the daily market summary endpoints
            object barMarketId = this.safeString(ticker, "T");
            object barTimestamp = this.safeInteger(ticker, "t");
            object barClose = this.safeString(ticker, "c");
            return this.safeTicker(new Dictionary<string, object>() {
                { "symbol", this.safeSymbol(barMarketId, market) },
                { "timestamp", barTimestamp },
                { "datetime", this.iso8601(barTimestamp) },
                { "high", this.safeString(ticker, "h") },
                { "low", this.safeString(ticker, "l") },
                { "bid", null },
                { "bidVolume", null },
                { "ask", null },
                { "askVolume", null },
                { "vwap", this.safeString(ticker, "vw") },
                { "open", this.safeString(ticker, "o") },
                { "close", barClose },
                { "last", barClose },
                { "previousClose", null },
                { "change", null },
                { "percentage", null },
                { "average", null },
                { "baseVolume", this.safeString(ticker, "v") },
                { "quoteVolume", null },
                { "info", ticker },
            }, market);
        }
        // snapshot shape
        object marketId = this.safeString(ticker, "ticker");
        object lastQuote = this.safeDict(ticker, "lastQuote", new Dictionary<string, object>() {});
        object lastTrade = this.safeDict(ticker, "lastTrade", new Dictionary<string, object>() {});
        object previousDay = this.safeDict(ticker, "prevDay", new Dictionary<string, object>() {});
        object timestamp = this.safeIntegerProduct(ticker, "updated", 0.000001);
        object last = this.safeString(lastTrade, "p");
        return this.safeTicker(new Dictionary<string, object>() {
            { "symbol", this.safeSymbol(marketId, market) },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "high", this.safeString(day, "h") },
            { "low", this.safeString(day, "l") },
            { "bid", this.safeString(lastQuote, "p") },
            { "bidVolume", this.safeString(lastQuote, "s") },
            { "ask", this.safeString(lastQuote, "P") },
            { "askVolume", this.safeString(lastQuote, "S") },
            { "vwap", this.safeString(day, "vw") },
            { "open", this.safeString(day, "o") },
            { "close", this.safeString(day, "c") },
            { "last", last },
            { "previousClose", this.safeString(previousDay, "c") },
            { "change", this.safeString(ticker, "todaysChange") },
            { "percentage", this.safeString(ticker, "todaysChangePerc") },
            { "average", null },
            { "baseVolume", this.safeString(day, "v") },
            { "quoteVolume", null },
            { "info", ticker },
        }, market);
    }

    /**
     * @method
     * @name massive#fetchOHLCV
     * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
     * @see https://massive.com/docs/rest/stocks/aggregates/custom-bars
     * @param {string} symbol unified symbol of the market to fetch OHLCV data for
     * @param {string} timeframe the length of time each candle represents
     * @param {int} [since] timestamp in ms of the earliest candle to fetch
     * @param {int} [limit] the maximum amount of candles to fetch, max 50000
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest candle to fetch
     * @param {boolean} [params.adjusted] whether the bars are adjusted for splits, defaults to true
     * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
     */
    public async override Task<List<ccxt.OHLCV>> FetchOHLCV(string symbol, string timeframe = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        object timeframeVar = timeframe;
        object sinceVar = since;
        object limitVar = limit;
        timeframeVar ??= "1d";
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        object market = this.market(symbol);
        object selectedTimeframe = this.safeString(this.timeframes, timeframeVar, timeframeVar);
        List<object> parts = ((string)selectedTimeframe).Split(new [] {((string)"/")}, StringSplitOptions.None).ToList<object>();
        int partsLength = getArrayLength(parts);
        if (isTrue(isLessThan(partsLength, 2)))
        {
            throw new BadRequest ((string)add(add(add(this.id, " fetchOHLCV() does not support the "), timeframeVar), " timeframe")) ;
        }
        object maxLimit = this.safeInteger(this.options, "maxOHLCVLimit", 50000);
        if (isTrue(isEqual(limitVar, null)))
        {
            limitVar = this.safeInteger(this.options, "defaultLimit", 1000);
        }
        limitVar = mathMin(limitVar, maxLimit);
        object until = this.safeInteger(parameters, "until");
        parameters = this.omit(parameters, new List<object>() {"until"});
        Int64 now = this.milliseconds();
        object duration = multiply(this.parseTimeframe(timeframeVar), 1000);
        string sort = "asc";
        if (isTrue(isEqual(sinceVar, null)))
        {
            // ask for the most recent candles instead of the oldest ones inside the window.
            // us equities trade ~6.5 hours a day, 5 days a week, so a window `limitVar` candles
            // wide in wall clock time always comes back short - widen it and let the exchange
            // cut it down to `limitVar`, parseOHLCVs sorts the result back into ascending order
            sort = "desc";
            if (isTrue(isEqual(until, null)))
            {
                until = now;
            }
            object windowFactor = this.safeInteger(this.options, "ohlcvWindowFactor", 10);
            sinceVar = subtract(until, (multiply(multiply(limitVar, duration), windowFactor)));
            if (isTrue(isLessThan(sinceVar, 0)))
            {
                sinceVar = 0;
            }
        } else if (isTrue(isEqual(until, null)))
        {
            object computedUntil = this.sum(sinceVar, multiply(limitVar, duration));
            if (isTrue(isGreaterThan(computedUntil, now)))
            {
                until = now;
            } else
            {
                until = computedUntil;
            }
        }
        // massive counts `limitVar` in base aggregates - seconds for the second timespan,
        // minutes for minute and hour, days for day and everything above it - and not in
        // returned candles, so a weekly request for 3 candles comes back with a single one
        object timespan = getValue(parts, 1);
        object baseDuration = multiply(multiply(multiply(24, 60), 60), 1000);
        if (isTrue(isEqual(timespan, "second")))
        {
            baseDuration = 1000;
        } else if (isTrue(isTrue((isEqual(timespan, "minute"))) || isTrue((isEqual(timespan, "hour")))))
        {
            baseDuration = multiply(60, 1000);
        }
        object requestLimit = this.parseToInt(divide(multiply(limitVar, duration), baseDuration));
        requestLimit = mathMin(requestLimit, maxLimit);
        object request = new Dictionary<string, object>() {
            { "stocksTicker", getValue(market, "id") },
            { "multiplier", getValue(parts, 0) },
            { "timespan", getValue(parts, 1) },
            { "from", sinceVar },
            { "to", until },
            { "limit", requestLimit },
            { "sort", sort },
            { "adjusted", true },
        };
        object response = await this.publicGetV2AggsTickerStocksTickerRangeMultiplierTimespanFromTo(this.extend(request, parameters));
        //
        //     {
        //         "ticker": "AAPL",
        //         "queryCount": 3,
        //         "resultsCount": 3,
        //         "adjusted": true,
        //         "results": [
        //             { "v": 75051951, "vw": 305.1311, "o": 309.58, "c": 303.42, "h": 311.8, "l": 302.56, "t": 1785729600000, "n": 1388685 }
        //         ],
        //         "status": "OK"
        //     }
        //
        object results = this.safeList(response, "results", new List<object>() {});
        // when no `sinceVar` was given the newest candles are the interesting ones, so trim
        // the over-fetched tail-end of the window from the front instead of from the back
        bool tail = (isEqual(sort, "desc"));
        return ccxt.BaseExchange.ToOHLCVList(this.parseOHLCVs(results, market, timeframeVar, sinceVar, limitVar, tail));
    }

    public override object parseOHLCV(object ohlcv, object market = null)
    {
        return new List<object> {this.safeInteger(ohlcv, "t"), this.safeNumber(ohlcv, "o"), this.safeNumber(ohlcv, "h"), this.safeNumber(ohlcv, "l"), this.safeNumber(ohlcv, "c"), this.safeNumber(ohlcv, "v")};
    }

    /**
     * @method
     * @name massive#fetchTrades
     * @description get the list of most recent trades for a particular symbol
     * @see https://massive.com/docs/rest/stocks/trades-quotes/trades
     * @param {string} symbol unified symbol of the market to fetch trades for
     * @param {int} [since] timestamp in ms of the earliest trade to fetch
     * @param {int} [limit] the maximum amount of trades to fetch, max 50000
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest trade to fetch
     * @returns {object[]} a list of [trade structures](https://docs.ccxt.com/#/?id=public-trades)
     */
    public async override Task<List<ccxt.Trade>> FetchTrades(string symbol, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        object market = this.market(symbol);
        object request = new Dictionary<string, object>() {
            { "stocksTicker", getValue(market, "id") },
            { "sort", "timestamp" },
            { "order", "desc" },
        };
        if (isTrue(!isEqual(limit, null)))
        {
            object maxLimit = this.safeInteger(this.options, "maxTradesLimit", 50000);
            ((IDictionary<string,object>)request)["limit"] = mathMin(limit, maxLimit);
        }
        if (isTrue(!isEqual(since, null)))
        {
            // the api works in nanoseconds, which overflows a double, keep it a string
            ((IDictionary<string,object>)request)["timestamp.gte"] = Precise.stringMul(this.numberToString(since), "1000000");
            ((IDictionary<string,object>)request)["order"] = "asc";
        }
        object until = this.safeInteger(parameters, "until");
        parameters = this.omit(parameters, new List<object>() {"until"});
        if (isTrue(!isEqual(until, null)))
        {
            ((IDictionary<string,object>)request)["timestamp.lte"] = Precise.stringMul(this.numberToString(until), "1000000");
        }
        object response = await this.publicGetV3TradesStocksTicker(this.extend(request, parameters));
        //
        //     {
        //         "request_id": "a47d1beb8c11b6ae897ab76cdbbf35a3",
        //         "status": "OK",
        //         "results": [
        //             {
        //                 "id": "1",
        //                 "exchange": 11,
        //                 "tape": 3,
        //                 "price": 171.55,
        //                 "size": 100,
        //                 "conditions": [ 12, 41 ],
        //                 "correction": 0,
        //                 "sequence_number": 1063,
        //                 "participant_timestamp": 1517562000015577000,
        //                 "sip_timestamp": 1517562000016036600
        //             }
        //         ]
        //     }
        //
        object results = this.safeList(response, "results", new List<object>() {});
        return ccxt.BaseExchange.ToTradeList(this.parseTrades(results, market, since, limit));
    }

    public override object parseTrade(object trade, object market = null)
    {
        object marketId = this.safeString(trade, "T");
        object resolved = this.safeMarket(marketId, market);
        object timestamp = this.safeIntegerProduct2(trade, "sip_timestamp", "participant_timestamp", 0.000001);
        return this.safeTrade(new Dictionary<string, object>() {
            { "id", this.safeString2(trade, "id", "i") },
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", getValue(resolved, "symbol") },
            { "order", null },
            { "type", null },
            { "side", null },
            { "takerOrMaker", null },
            { "price", this.safeString2(trade, "price", "p") },
            { "amount", this.safeString2(trade, "size", "s") },
            { "cost", null },
            { "fee", null },
        }, resolved);
    }

    /**
     * @method
     * @name massive#fetchOrderBook
     * @description fetches the top of the consolidated order book, massive publishes the national best bid and offer, not the full depth of book
     * @see https://massive.com/docs/rest/stocks/trades-quotes/last-quote
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {int} [limit] not used by massive.fetchOrderBook, the nbbo carries a single level per side
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} A dictionary of [order book structures](https://docs.ccxt.com/#/?id=order-book-structure) indexed by market symbols
     */
    public async override Task<object> fetchOrderBook(string symbol, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        object market = this.market(symbol);
        object request = new Dictionary<string, object>() {
            { "stocksTicker", getValue(market, "id") },
        };
        object response = await this.publicGetV2LastNbboStocksTicker(this.extend(request, parameters));
        //
        //     {
        //         "request_id": "b84e24636301f19f88e0dfbf9a45ed5c",
        //         "status": "OK",
        //         "results": {
        //             "P": 127.98,
        //             "S": 7,
        //             "T": "AAPL",
        //             "X": 19,
        //             "p": 127.96,
        //             "q": 83480742,
        //             "s": 1,
        //             "t": 1617827221349730300,
        //             "x": 11,
        //             "y": 1617827221349366000,
        //             "z": 3
        //         }
        //     }
        //
        object result = this.safeDict(response, "results", new Dictionary<string, object>() {});
        object timestamp = this.safeIntegerProduct(result, "t", 0.000001);
        object bids = new List<object>() {};
        object asks = new List<object>() {};
        object bidPrice = this.safeString(result, "p");
        object bidAmount = this.safeString(result, "s");
        if (isTrue(isTrue((!isEqual(bidPrice, null))) && isTrue(Precise.stringGt(bidPrice, "0"))))
        {
            ((IList<object>)bids).Add(new List<object>() {bidPrice, bidAmount});
        }
        object askPrice = this.safeString(result, "P");
        object askAmount = this.safeString(result, "S");
        if (isTrue(isTrue((!isEqual(askPrice, null))) && isTrue(Precise.stringGt(askPrice, "0"))))
        {
            ((IList<object>)asks).Add(new List<object>() {askPrice, askAmount});
        }
        object rawOrderBook = new Dictionary<string, object>() {
            { "bids", bids },
            { "asks", asks },
        };
        object orderbook = this.parseOrderBook(rawOrderBook, getValue(market, "symbol"), timestamp);
        ((IDictionary<string,object>)orderbook)["nonce"] = this.safeInteger(result, "q");
        return orderbook;
    }

    public override object sign(object path, object api = null, object method = null, object parameters = null, object headers = null, object body = null)
    {
        // every massive endpoint is authenticated, the api key entitles the
        // caller to a data feed, it is not bound to a trading account
        api ??= "public";
        method ??= "GET";
        parameters ??= new Dictionary<string, object>();
        this.checkRequiredCredentials();
        object request = add("/", this.implodeParams(path, parameters));
        object url = add(this.implodeHostname(getValue(getValue(this.urls, "api"), "public")), request);
        object query = this.omit(parameters, this.extractParams(path));
        int queryLength = getArrayLength(new List<object>(((IDictionary<string,object>)query).Keys));
        if (isTrue(isGreaterThan(queryLength, 0)))
        {
            url = add(url, add("?", this.urlencode(query)));
        }
        headers = new Dictionary<string, object>() {
            { "Authorization", add("Bearer ", this.apiKey) },
            { "Accept", "application/json" },
        };
        return new Dictionary<string, object>() {
            { "url", url },
            { "method", method },
            { "body", body },
            { "headers", headers },
        };
    }

    public override object handleErrors(object code, object reason, object url, object method, object headers, object body, object response, object requestHeaders, object requestBody)
    {
        if (isTrue(isEqual(response, null)))
        {
            return null;  // fallback to the default error handler
        }
        object status = this.safeString(response, "status");
        // DELAYED is a successful response on the delayed data plans
        if (isTrue(isTrue((isEqual(status, "OK"))) || isTrue((isEqual(status, "DELAYED")))))
        {
            return null;
        }
        object error = this.safeString2(response, "error", "message");
        if (isTrue(isTrue((isEqual(status, null))) && isTrue((isEqual(error, null)))))
        {
            return null;
        }
        //
        //     { "status": "NOT_AUTHORIZED", "request_id": "943c", "message": "You are not entitled to this data." }
        //     { "status": "ERROR", "request_id": "943c", "error": "Unknown API Key" }
        //
        object feedback = add(add(this.id, " "), body);
        this.throwExactlyMatchedException(getValue(this.exceptions, "exact"), error, feedback);
        this.throwBroadlyMatchedException(getValue(this.exceptions, "broad"), error, feedback);
        this.throwExactlyMatchedException(getValue(this.exceptions, "exact"), status, feedback);
        throw new ExchangeError ((string)feedback) ;
    }
}
